CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), login_name text UNIQUE, name text NOT NULL, role text NOT NULL CHECK(role IN('salesperson','admin','hospital')), password_hash text, active boolean NOT NULL DEFAULT true);
CREATE TABLE hospitals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, sales_user_id uuid NOT NULL REFERENCES users, payment_term_days integer NOT NULL DEFAULT 90 CHECK(payment_term_days BETWEEN 0 AND 3650));
CREATE TABLE hospital_purchasers(user_id uuid PRIMARY KEY REFERENCES users, hospital_id uuid NOT NULL REFERENCES hospitals, active boolean NOT NULL DEFAULT true, UNIQUE(hospital_id,user_id));
CREATE TABLE manufacturers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,active boolean NOT NULL DEFAULT true);
CREATE TABLE auth_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users,token_hash text UNIQUE NOT NULL,channel text NOT NULL CHECK(channel IN('mini','trial')),expires_at timestamptz NOT NULL,last_seen_at timestamptz NOT NULL,revoked_at timestamptz);
CREATE TABLE wechat_identities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),app_id text NOT NULL,open_id text NOT NULL,user_id uuid NOT NULL REFERENCES users,UNIQUE(app_id,open_id),UNIQUE(app_id,user_id));
CREATE TABLE bind_tickets(token_hash text PRIMARY KEY,app_id text NOT NULL,open_id text NOT NULL,expires_at timestamptz NOT NULL,used_at timestamptz);
CREATE TABLE document_number_counters(business_date date PRIMARY KEY,value integer NOT NULL CHECK(value BETWEEN 1 AND 9999));
CREATE TABLE purchase_orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_no text UNIQUE NOT NULL,hospital_id uuid NOT NULL REFERENCES hospitals,purchaser_user_id uuid NOT NULL, sales_user_id uuid NOT NULL REFERENCES users,original_sales_user_id uuid NOT NULL REFERENCES users,received_date date NOT NULL,payment_term_days integer NOT NULL CHECK(payment_term_days BETWEEN 0 AND 3650),current_revision_no integer NOT NULL DEFAULT 1,row_version integer NOT NULL DEFAULT 1,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','frozen','quote_draft')),created_at timestamptz NOT NULL,FOREIGN KEY(hospital_id,purchaser_user_id) REFERENCES hospital_purchasers(hospital_id,user_id));
CREATE TABLE purchase_order_revisions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),purchase_order_id uuid NOT NULL REFERENCES purchase_orders,revision_no integer NOT NULL DEFAULT 1,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','frozen','superseded')),frozen_at timestamptz,UNIQUE(purchase_order_id,revision_no),UNIQUE(id,purchase_order_id));
CREATE TABLE purchase_order_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),revision_id uuid NOT NULL REFERENCES purchase_order_revisions,position integer NOT NULL,name text NOT NULL CHECK(length(trim(name))>0),spec text NOT NULL DEFAULT '',quantity numeric(12,2) NOT NULL CHECK(quantity>0),unit text NOT NULL DEFAULT 'kg' CHECK(unit='kg'),checked boolean NOT NULL DEFAULT false,UNIQUE(revision_id,position),UNIQUE(id,revision_id));
CREATE FUNCTION protect_frozen_lines() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP IN('UPDATE','DELETE') THEN IF EXISTS(SELECT 1 FROM purchase_order_revisions WHERE id=OLD.revision_id AND status<>'draft') THEN RAISE EXCEPTION 'frozen purchase lines are immutable';END IF;END IF;IF TG_OP IN('UPDATE','INSERT') THEN IF EXISTS(SELECT 1 FROM purchase_order_revisions WHERE id=NEW.revision_id AND status<>'draft') THEN RAISE EXCEPTION 'frozen purchase lines are immutable';END IF;END IF;IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;END $$;
CREATE TRIGGER frozen_lines_guard BEFORE INSERT OR UPDATE OR DELETE ON purchase_order_lines FOR EACH ROW EXECUTE FUNCTION protect_frozen_lines();
CREATE TABLE supplier_tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),revision_id uuid NOT NULL REFERENCES purchase_order_revisions,manufacturer_id uuid NOT NULL REFERENCES manufacturers,slot_no integer NOT NULL CHECK(slot_no IN(1,2)),status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','submitted','requote','cancelled')),UNIQUE(id,revision_id));
CREATE UNIQUE INDEX task_slot_unique ON supplier_tasks(revision_id,slot_no) WHERE status<>'cancelled';
CREATE UNIQUE INDEX task_factory_unique ON supplier_tasks(revision_id,manufacturer_id) WHERE status<>'cancelled';
CREATE TABLE supplier_links(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),task_id uuid NOT NULL REFERENCES supplier_tasks,token_hash text UNIQUE NOT NULL,expires_at timestamptz NOT NULL,status text NOT NULL DEFAULT 'active' CHECK(status IN('active','used','revoked')),created_at timestamptz NOT NULL);
CREATE UNIQUE INDEX task_active_link_unique ON supplier_links(task_id) WHERE status='active';
CREATE TABLE supplier_sessions(token_hash text PRIMARY KEY,link_id uuid NOT NULL REFERENCES supplier_links,expires_at timestamptz NOT NULL);
CREATE TABLE supplier_quote_submissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),task_id uuid NOT NULL,revision_id uuid NOT NULL,submission_no integer NOT NULL,valid_until date NOT NULL,status text NOT NULL DEFAULT 'current' CHECK(status IN('current','superseded')),created_at timestamptz NOT NULL,UNIQUE(task_id,submission_no),UNIQUE(id,revision_id),FOREIGN KEY(task_id,revision_id) REFERENCES supplier_tasks(id,revision_id));
CREATE UNIQUE INDEX current_submission_unique ON supplier_quote_submissions(task_id) WHERE status='current';
CREATE TABLE supplier_quote_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),submission_id uuid NOT NULL,revision_id uuid NOT NULL,purchase_line_id uuid NOT NULL,status text NOT NULL CHECK(status IN('quoted','unavailable')),unit_price numeric(12,2),CHECK((status='quoted' AND unit_price IS NOT NULL AND unit_price>0) OR (status='unavailable' AND unit_price IS NULL)),UNIQUE(submission_id,purchase_line_id),UNIQUE(id,purchase_line_id,revision_id),FOREIGN KEY(submission_id,revision_id) REFERENCES supplier_quote_submissions(id,revision_id),FOREIGN KEY(purchase_line_id,revision_id) REFERENCES purchase_order_lines(id,revision_id));
CREATE FUNCTION preserve_supplier_quote_line() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'supplier prices are immutable';END $$;
CREATE TRIGGER supplier_quote_line_guard BEFORE UPDATE OR DELETE ON supplier_quote_lines FOR EACH ROW EXECUTE FUNCTION preserve_supplier_quote_line();
CREATE TABLE quotes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),purchase_order_id uuid NOT NULL REFERENCES purchase_orders,revision_id uuid UNIQUE NOT NULL,created_by uuid NOT NULL REFERENCES users,FOREIGN KEY(revision_id,purchase_order_id) REFERENCES purchase_order_revisions(id,purchase_order_id),UNIQUE(id,revision_id));
CREATE TABLE quote_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),quote_id uuid NOT NULL,revision_id uuid NOT NULL,version_no integer NOT NULL DEFAULT 1,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','exported','sent','confirmed','void')),row_version integer NOT NULL DEFAULT 1,hospital_valid_until date,FOREIGN KEY(quote_id,revision_id) REFERENCES quotes(id,revision_id),UNIQUE(quote_id,version_no),UNIQUE(id,revision_id));
CREATE UNIQUE INDEX one_draft_unique ON quote_versions(quote_id) WHERE status='draft';
CREATE TABLE quote_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),version_id uuid NOT NULL,revision_id uuid NOT NULL,purchase_line_id uuid NOT NULL,base_supplier_quote_line_id uuid,base_price numeric(12,2),selection_mode text NOT NULL DEFAULT 'auto' CHECK(selection_mode IN('auto','manual')),markup_method text CHECK(markup_method IN('fixed','percent','multiplier')),parameter_value numeric(12,2),recommended_price numeric(12,2),final_price numeric(12,2) CHECK(final_price>0),final_confirmed boolean NOT NULL DEFAULT false,loss_reason text NOT NULL DEFAULT '',UNIQUE(version_id,purchase_line_id),FOREIGN KEY(version_id,revision_id) REFERENCES quote_versions(id,revision_id),FOREIGN KEY(purchase_line_id,revision_id) REFERENCES purchase_order_lines(id,revision_id),FOREIGN KEY(base_supplier_quote_line_id,purchase_line_id,revision_id) REFERENCES supplier_quote_lines(id,purchase_line_id,revision_id));
ALTER TABLE quote_lines ADD COLUMN adopted_kind text NOT NULL DEFAULT 'blocked' CHECK(adopted_kind IN('priced','missing','blocked'));
ALTER TABLE quote_lines ADD COLUMN adopted_supplier_snapshot jsonb NOT NULL DEFAULT '[]';
ALTER TABLE quote_lines ADD COLUMN adopted_lowest_price numeric(12,2);
ALTER TABLE quote_lines ADD CONSTRAINT base_price_reference CHECK((base_supplier_quote_line_id IS NULL AND base_price IS NULL) OR (base_supplier_quote_line_id IS NOT NULL AND base_price IS NOT NULL AND base_price>0));
CREATE TABLE operation_requests(actor_type text NOT NULL CHECK(actor_type IN('user','supplier')),actor_id uuid NOT NULL,idempotency_key text NOT NULL,operation text NOT NULL,content_hash text NOT NULL,result jsonb NOT NULL,created_at timestamptz NOT NULL,PRIMARY KEY(actor_type,actor_id,idempotency_key));
CREATE TABLE audit_records(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),purchase_order_id uuid REFERENCES purchase_orders,actor_id uuid NOT NULL,action text NOT NULL,details jsonb NOT NULL,created_at timestamptz NOT NULL);
CREATE INDEX orders_owner_date ON purchase_orders(sales_user_id,received_date DESC,id);
CREATE INDEX orders_hospital ON purchase_orders(hospital_id);
